import{_ as l,r as t,o as i,c as r,e,a as n,s as o,d as a}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"注册(登记) - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":3,"title":"目录结构","slug":"目录结构","link":"#目录结构","children":[]},{"level":3,"title":"插件命名空间","slug":"插件命名空间","link":"#插件命名空间","children":[]},{"level":2,"title":"注册文件","slug":"注册文件","link":"#注册文件","children":[{"level":3,"title":"注册方法","slug":"注册方法","link":"#注册方法","children":[]},{"level":3,"title":"基本插件信息","slug":"基本插件信息","link":"#基本插件信息","children":[]}]},{"level":2,"title":"路由和初始化","slug":"路由和初始化","link":"#路由和初始化","children":[]},{"level":2,"title":"依赖定义","slug":"依赖定义","link":"#依赖定义","children":[]},{"level":2,"title":"扩展Twig","slug":"扩展twig","link":"#扩展twig","children":[]},{"level":2,"title":"导航菜单","slug":"导航菜单","link":"#导航菜单","children":[{"level":3,"title":"导航计数器","slug":"导航计数器","link":"#导航计数器","children":[]}]},{"level":2,"title":"注册中间件","slug":"注册中间件","link":"#注册中间件","children":[]}],"relativePath":"2.x/zh-cn/plugin/registration.md","filePath":"2.x/zh-cn/plugin/registration.md"}'),u={name:"2.x/zh-cn/plugin/registration.md"};function g(k,s,d,h,m,f){const p=t("pre-heading"),c=t("post-heading");return i(),r("div",null,[e(p),s[0]||(s[0]=n("h1",null,"注册(登记)",-1)),e(c),s[1]||(s[1]=o(`<p>插件是通过扩展向 CMS 添加新功能的基础。 本文介绍了组件注册。 注册过程允许插件声明其功能，例如 <a href="./components.html">组件</a> 或后端菜单和页面。 插件可以做什么的一些例子：</p><ol><li>定义<a href="./components.html">组件</a>。</li><li>定义<a href="./../backend/users.html">用户权限</a>。</li><li>添加<a href="./settings.html#oc-backend-settings-pages">设置页面</a>、<a href="#oc-navigation-menus">菜单项</a>、<a href="./../backend/lists.html">列表</a> 和[表单](.. /backend/forms.md)。</li><li>创建<a href="./updates.html">数据库表结构和种子数据</a>。</li><li>更改<a href="./events.html">核心或其他插件的功能</a>。</li><li>提供类、<a href="./../backend/controllers-ajax.html">后端控制器</a>、视图、资产等文件。</li></ol><h3 id="目录结构"><a href="#目录结构" class="header-anchor">#</a> 目录结构</h3><p>插件驻留在应用程序目录的 <strong>/plugins</strong> 子目录中。 插件目录结构示例：</p><div class="language- extra-class"><pre class="language-text"><code>plugins/
  acme/            &lt;=== 作者/厂商名称
    blog/          &lt;=== 插件名称
      classes/
      components/
      controllers/
      models/
      updates/
      ...
      Plugin.php   &lt;=== 插件注册文件
</code></pre></div><p>并非所有插件目录都是必需的。 唯一需要的文件是下面描述的<strong>Plugin.php</strong>。 如果您的插件仅提供一个 <a href="./components.html">部件</a>，您的插件目录可能会简单得多，如下所示：</p><div class="language- extra-class"><pre class="language-text"><code>plugins/
  acme/            &lt;=== 作者/厂商名称
    blog/          &lt;=== 插件名称
      components/
      Plugin.php   &lt;=== 插件注册文件
</code></pre></div>`,7)),s[2]||(s[2]=n("blockquote",null,[n("p",null,[n("strong",null,"注意"),a("：如果您正在为"),n("a",{href:"https://octobercms.com/help/site/marketplace",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("市场"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])]),a(" 开发插件，则需要"),n("a",{href:"./updates.html"},"updates/version.yaml"),a(" 文件。")])],-1)),s[3]||(s[3]=n("p",null,[n("a",{id:"oc-plugin-namespaces"})],-1)),s[4]||(s[4]=n("h3",{id:"插件命名空间"},[n("a",{href:"#插件命名空间",class:"header-anchor"},"#"),a(" 插件命名空间")],-1)),s[5]||(s[5]=n("p",null,[a("插件命名空间是必不可少的，特别是如果您打算在 "),n("a",{href:"https://octobercms.com/plugins",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("October市场"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])]),a(" 上发布您的插件。当您在市场上注册为作者时，系统会要求您提供作者代码，该代码是所有插件的根命名空间。注册时只能指定一次作者代码。 市场提供的默认作者代码由作者名字和姓氏组成：JohnSmith。注册后无法更改代码。你所有的插件命名空间都应该在根命名空间下定义，例如"),n("code",null,"\\JohnSmith\\Blog"),a("。")],-1)),s[6]||(s[6]=o(`<p><a id="oc-registration-file"></a></p><h2 id="注册文件"><a href="#注册文件" class="header-anchor">#</a> 注册文件</h2><p><strong>Plugin.php</strong> 文件，称为<em>插件注册文件</em>，是一个初始化脚本，声明了插件的核心功能和信息。注册文件可以提供以下内容：</p><ol><li>插件信息、插件名称和作者。</li><li>扩展CMS的注册方法。</li></ol><p>注册文件应该使用插件命名空间。注册文件应该定义一个名为<code>Plugin</code>的类，它扩展了<code>\\System\\Classes\\PluginBase</code>类。插件注册类唯一需要的方法是<code>pluginDetails</code>。插件注册文件示例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Plugin</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>PluginBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">pluginDetails</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;博客插件&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;提供一些非常酷的博客功能。&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;author&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;ACME 公司&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-leaf&#39;</span>
        <span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerComponents</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span>
            <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Components<span class="token punctuation">\\</span>Post</span><span class="token operator">::</span><span class="token keyword">class</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;blogPost&#39;</span>
        <span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p><a id="oc-registration-methods"></a></p><h3 id="注册方法"><a href="#注册方法" class="header-anchor">#</a> 注册方法</h3><p>插件注册类支持以下方法：</p><div class="table"><table tabindex="0"><thead><tr><th>方法</th><th>描述</th></tr></thead><tbody><tr><td><strong>pluginDetails()</strong></td><td>返回有关插件的信息。</td></tr><tr><td><strong>register()</strong></td><td>register 方法，在插件首次注册时调用。</td></tr><tr><td><strong>boot()</strong></td><td>boot 方法，在请求路由之前调用。</td></tr><tr><td><strong>registerMarkupTags()</strong></td><td>注册可在 CMS 中使用的 <a href="#oc-extending-twig">附加标记标签</a>。</td></tr><tr><td><strong>registerComponents()</strong></td><td>注册此插件使用的任何 <a href="./components.html#oc-component-registration">前端组件</a>。</td></tr><tr><td><strong>registerNavigation()</strong></td><td>为这个插件注册<a href="#oc-navigation-menus">后端导航菜单项</a>。</td></tr><tr><td><strong>registerPermissions()</strong></td><td>注册此插件使用的任何 <a href="./../backend/users.html#oc-registering-permissions">后端权限</a>。</td></tr><tr><td><strong>registerSettings()</strong></td><td>注册此插件使用的任何 <a href="./settings.html#oc-settings-link-registration">后端配置链接</a>。</td></tr><tr><td><strong>registerFormWidgets()</strong></td><td>注册此插件提供的任何 <a href="./../backend/widgets.html#oc-form-widget-registration">后端表单小部件</a>。</td></tr><tr><td><strong>registerReportWidgets()</strong></td><td>注册任何 <a href="./../backend/widgets.html#oc-report-widget-registration">后端报告小部件</a>，包括仪表板小部件。</td></tr><tr><td><strong>registerListColumnTypes()</strong></td><td>注册此插件提供的任何 <a href="./../backend/lists.html#oc-custom-column-types">自定义列表字段类型</a>。</td></tr><tr><td><strong>registerMailLayouts()</strong></td><td>注册此插件提供的任何 <a href="./mail.html#oc-registering-mail-layouts-templates-partials">邮件视图布局</a>。</td></tr><tr><td><strong>registerMailTemplates()</strong></td><td>注册此插件提供的任何 <a href="./mail.html#oc-registering-mail-layouts-templates-partials">邮件视图模板</a>。</td></tr><tr><td><strong>registerMailPartials()</strong></td><td>注册此插件提供的任何 <a href="./mail.html#oc-registering-mail-layouts-templates-partials">邮件视图部件</a>。</td></tr><tr><td><strong>registerSchedule()</strong></td><td>注册定期执行的 <a href="./../plugin/scheduling.html#oc-defining-schedules">计划任务</a>。</td></tr></tbody></table></div><h3 id="基本插件信息"><a href="#基本插件信息" class="header-anchor">#</a> 基本插件信息</h3><p><code>pluginDetails</code> 是插件注册类的必需方法。 它应该返回一个包含以下键的数组：</p><div class="table"><table tabindex="0"><thead><tr><th>键</th><th>描述</th></tr></thead><tbody><tr><td><strong>name</strong></td><td>插件名称，必填。</td></tr><tr><td><strong>description</strong></td><td>插件描述，必填。</td></tr><tr><td><strong>author</strong></td><td>插件作者姓名，必填。</td></tr><tr><td><strong>icon</strong></td><td>插件图标的名称。 可用图标的完整列表可以在 <a href="./../ui/icon.html">UI 文档</a> 中找到。 此字体提供的任何图标名称都是有效的，例如 <strong>icon-glass</strong>、<strong>icon-music</strong>，可选。</td></tr><tr><td><strong>iconSvg</strong></td><td>用于代替标准图标的 SVG 图标。 SVG 图标应该是一个矩形并且可以支持颜色，可选。</td></tr><tr><td><strong>homepage</strong></td><td>指向作者网站地址的链接，可选。</td></tr></tbody></table></div><p><a id="oc-routing-and-initialization"></a></p><h2 id="路由和初始化"><a href="#路由和初始化" class="header-anchor">#</a> 路由和初始化</h2><p>插件注册文件可以包含两个方法<code>boot</code>和<code>register</code>。 使用这些方法，您可以做任何您喜欢的事情，例如注册路由或将处理程序附加到事件。</p><p>注册插件时会立即调用 register 方法。 <code>boot</code> 方法在请求被路由之前被调用。 因此，如果您的操作依赖于另一个插件，则应使用 boot 方法。 例如，在 <code>boot</code> 方法中，您可以扩展模型：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">boot</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">hasOne</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;author&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Author</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>插件还可以提供一个名为 <strong>routes.php</strong> 的文件，其中包含自定义路由逻辑，如 <a href="./../services/router.html">路由服务</a> 中定义的。 例如：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Route</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;api_acme_blog/cleanup_posts&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Posts</span><span class="token operator">::</span><span class="token function">cleanUp</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="oc-dependency-definitions"></a></p><h2 id="依赖定义"><a href="#依赖定义" class="header-anchor">#</a> 依赖定义</h2><p>插件可以通过在<a href="#oc-registration-file">插件注册文件</a> 中定义<code>$require</code> 属性来依赖其他插件，该属性应包含被视为需求的插件名称数组。 依赖 <strong>Acme.User</strong> 插件的插件可以通过以下方式声明此要求：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Plugin</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>PluginBase</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * @var array 插件依赖
     */</span>
    <span class="token keyword">public</span> <span class="token variable">$require</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;Acme.User&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><p>依赖定义将影响插件的运行方式和<a href="./../plugin/updates.html">更新过程如何应用更新</a>。 安装过程将尝试自动安装任何依赖项，但是如果在系统中检测到没有任何依赖项的插件，它将被禁用以防止系统错误。</p><p>依赖定义可能很复杂，但应注意防止循环引用。 依赖图应该始终是有向的，循环依赖被认为是设计错误。</p><p><a id="oc-extending-twig"></a></p><h2 id="扩展twig"><a href="#扩展twig" class="header-anchor">#</a> 扩展Twig</h2><p>可以使用插件注册类的<code>registerMarkupTags</code> 方法在CMS中注册自定义Twig过滤器和函数。下一个示例注册两个 Twig 过滤器和两个函数。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMarkupTags</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;filters&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token comment">// 一个全局函数，即 str_plural()</span>
            <span class="token string single-quoted-string">&#39;plural&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;str_plural&#39;</span><span class="token punctuation">,</span>

            <span class="token comment">// 本地方法，即 $this-&gt;makeTextAllCaps()</span>
            <span class="token string single-quoted-string">&#39;uppercase&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token variable">$this</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;makeTextAllCaps&#39;</span><span class="token punctuation">]</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;functions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token comment">// 静态方法调用，即 Form::open()</span>
            <span class="token string single-quoted-string">&#39;form_open&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Html<span class="token punctuation">\\</span>Form</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;open&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>

            <span class="token comment">// 使用内联闭包</span>
            <span class="token string single-quoted-string">&#39;helloWorld&#39;</span> <span class="token operator">=&gt;</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Hello World!&#39;</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">makeTextAllCaps</span><span class="token punctuation">(</span><span class="token variable">$text</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token function">strtoupper</span><span class="token punctuation">(</span><span class="token variable">$text</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><a id="oc-navigation-menus"></a></p><h2 id="导航菜单"><a href="#导航菜单" class="header-anchor">#</a> 导航菜单</h2><p>插件可以通过覆盖<a href="#oc-registration-file">插件注册类</a>的<code>registerNavigation</code>方法来扩展后端导航菜单。 本节向您展示如何将菜单项添加到后端导航区域。 注册具有两个子菜单项的顶级导航菜单项的示例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerNavigation</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;blog&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;博客&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/posts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-pencil&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;permissions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.*&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">500</span><span class="token punctuation">,</span>

            <span class="token string single-quoted-string">&#39;sideMenu&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;posts&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;帖子&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-copy&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/posts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;permissions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.access_posts&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">&#39;categories&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;分类&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-copy&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/categories&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;permissions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.access_categories&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token punctuation">]</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>当您注册后端导航时，您可以将 <a href="./localization.html">多语言字符串</a> 用于 <code>label</code> 值。 后端导航也可以由<code>permissions</code> 值控制并对应于定义的<a href="./../backend/users.html">后端用户权限</a>。 后端导航出现在整个导航菜单项上的顺序由 <code>order</code> 值控制。 较高的数字意味着该项目将在菜单项的顺序中稍后出现，而较低的数字意味着它将较早出现。</p><p>要使子菜单项可见，您可以在后端控制器中使用 <code>BackendMenu::setContext</code> <a href="./../backend/controllers-ajax.html#oc-setting-the-navigation-context">设置导航上下文</a>方法。 这将使父菜单项处于活动状态并在侧菜单中显示子项。</p><div class="table"><table tabindex="0"><thead><tr><th>键</th><th>描述</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>指定菜单标签多语言字符串键，必需。</td></tr><tr><td><strong>icon</strong></td><td>来自 <a href="./../ui/icon.html">October CMS 图标集</a> 的图标名称，可选。</td></tr><tr><td><strong>iconSvg</strong></td><td>用于代替标准图标的SVG图标，SVG图标应该是一个矩形并且可以支持颜色，可选。</td></tr><tr><td><strong>url</strong></td><td>菜单项应指向的 URL(例如，<code>Backend::url(&#39;author/plugin/controller/action&#39;)</code>，必需。</td></tr><tr><td><strong>counter</strong></td><td>要在菜单图标附近输出的数值。 该值应该是一个数字或一个返回数字的可调用对象，可选。</td></tr><tr><td><strong>counterLabel</strong></td><td>一个字符串值，用于描述计数器中的数字引用，可选。</td></tr><tr><td><strong>attributes</strong></td><td>要应用于菜单项的属性和值的关联数组，可选。</td></tr><tr><td><strong>permissions</strong></td><td>后端用户必须拥有的一组权限才能查看菜单项(注意：直接访问 URL 仍然需要单独的权限检查)，可选。</td></tr></tbody></table></div><p>以下是系统生成的值，在注册导航项时不提供。</p><div class="table"><table tabindex="0"><thead><tr><th>键</th><th>描述</th></tr></thead><tbody><tr><td><strong>code</strong></td><td>作为该菜单选项的唯一标识符的字符串值。</td></tr><tr><td><strong>owner</strong></td><td>以&quot;Author.Plugin&quot;格式指定菜单项所有者插件或模块的字符串值。</td></tr></tbody></table></div><h3 id="导航计数器"><a href="#导航计数器" class="header-anchor">#</a> 导航计数器</h3><p>导航项支持指定徽章或计数器以指示存在需要注意的项。 这些属性可用于父菜单项和子菜单项。 使用 <strong>counter</strong> 和 <strong>counterLabel</strong> 来显示数字计数器。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;blog&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token comment">// ...</span>
    <span class="token string single-quoted-string">&#39;counter&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Author<span class="token punctuation">\\</span>Plugin<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>MyMenuCounterService</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;getCounterMethod&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;counterLabel&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;描述动态菜单计数器的标签&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h2 id="注册中间件"><a href="#注册中间件" class="header-anchor">#</a> 注册中间件</h2><p>要注册自定义中间件，您可以使用以下方法扩展 Controller 类。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">boot</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Cms<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>CmsController</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">middleware</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Path<span class="token punctuation">\\</span>To<span class="token punctuation">\\</span>Custom<span class="token punctuation">\\</span>Middleware</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>或者，您可以通过以下方式将其直接推送到内核中。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">boot</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// 在堆栈的开头添加一个新的中间件。</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">app</span><span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Illuminate<span class="token punctuation">\\</span>Contracts<span class="token punctuation">\\</span>Http<span class="token punctuation">\\</span>Kernel</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">]</span>
            <span class="token operator">-&gt;</span><span class="token function">prependMiddleware</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Path\\To\\Custom\\Middleware&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// 将新的中间件添加到堆栈的末尾。</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">app</span><span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Illuminate<span class="token punctuation">\\</span>Contracts<span class="token punctuation">\\</span>Http<span class="token punctuation">\\</span>Kernel</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">]</span>
            <span class="token operator">-&gt;</span><span class="token function">pushMiddleware</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Path\\To\\Custom\\Middleware&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,47))])}const y=l(u,[["render",g]]);export{v as __pageData,y as default};
